mapper.select:
SELECT ミーティング一覧の見出し.ミーティング番号, ミーティング一覧の見出し.件名, 日程.日程番号, 日程.開催日, 日程.開始時間, 日程.開始分, 日程.会議時間 FROM (SELECT DISTINCT ミーティング.ミーティング番号, ミーティング.件名 FROM ミーティング._ミーティング AS ミーティング INNER JOIN 主催者._ミーティングと主催者 AS ミーティングと主催者 ON ミーティングと主催者.ミーティング番号 = ミーティング.ミーティング番号 INNER JOIN 日程候補._日程 AS 日程 ON 日程.ミーティング番号 = ミーティング.ミーティング番号 LEFT JOIN ミーティング._ミーティングメモ AS ミーティングメモ ON ミーティングメモ.ミーティング番号 = ミーティング.ミーティング番号 WHERE ミーティングと主催者.主催者番号 = #{organizerNumber.value} AND 日程.開催日 BETWEEN #{startDate.value} AND #{endDate.value}
AND (ミーティング.件名 LIKE #{keywordCondition} OR ミーティングメモ.メモ LIKE #{keywordCondition})
LIMIT #{limitCount.value}) AS ミーティング一覧の見出し INNER JOIN 日程候補._日程 AS 日程 ON 日程.ミーティング番号 = ミーティング一覧の見出し.ミーティング番号 WHERE 日程.開催日 BETWEEN #{startDate.value} AND #{endDate.value} ORDER BY ミーティング番号, 開催日, 開始時間, 開始分, 会議時間
